ALTER TABLE "provider_event_receipts" ADD CONSTRAINT "provider_event_receipts_pre_routing_drop_check" CHECK ("provider_event_receipts"."pre_routing_drop" is null or ("provider_event_receipts"."pre_routing_drop" in ('no_project_route', 'no_trigger_for_source', 'configuration_unavailable', 'unsupported_event')
        and ("provider_event_receipts"."pre_routing_drop" <> 'unsupported_event' or "provider_event_receipts"."provider" = 'linear')
        and "provider_event_receipts"."pre_routing_drop" is not distinct from "provider_event_receipts"."dropped_reason" and "provider_event_receipts"."accepted_routes" is null));